+/**
+ * Runs an agent until it completes. A delegate_task tool use recursively runs the
+ * target agent, then starts this agent again with the matching tool_result in its
+ * conversation context.
+ */
+async function* runAgentConversation(
+  agentId: string,
+  request: ChatRequest,
+  instructions: string,
+  abortController: AbortController,
+  debugMode: boolean,
+  delegationPath: string[],
+  streamText: boolean,
+): AsyncGenerator<StreamResponse, AgentRunResult> {
+  const provider = globalRegistry.getProviderForAgent(agentId);
+  const agentConfig = globalRegistry.getAgent(agentId);
+
+  if (!provider || !agentConfig) {
+    return { content: `Agent '${agentId}' not found or provider not available`, isError: true };
+  }
+
+  const context: ProviderChatRequest["context"] = [];
+  let accumulatedText = "";
+  let invocation = 0;
+
+  while (true) {
+    const providerRequest: ProviderChatRequest = {
+      // Delegated agents receive exactly the delegated instructions.
+      message: instructions,
+      sessionId: request.sessionId,
+      requestId: `${request.requestId}:agent:${agentId}:${invocation++}`,
+      workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
+      ...(context.length ? { context } : {}),
+    };
+
+    let delegated = false;
+    for await (const response of provider.executeChat(providerRequest, {
+      debugMode,
+      abortController,
+      temperature: agentConfig.config?.temperature,
+      maxTokens: agentConfig.config?.maxTokens,
+    })) {
+      if (response.type === "text") {
+        const text = response.content || "";
+        accumulatedText += text;
+        if (streamText) {
+          const chatRoomMessage = createChatRoomMessage(response, agentId);
+          if (chatRoomMessage) {
+            yield { type: "claude_json", data: { type: "chat_room_message", message: chatRoomMessage, session_id: request.sessionId } };
+          }
+          yield { type: "claude_json", data: { type: "assistant", content: text, model: response.metadata?.model } };
+        }
+        continue;
+      }
+
+      if (response.type === "error") {
+        return { content: response.error || `Agent '${agentId}' failed`, isError: true };
+      }
+
+      if (response.type !== "tool_use" || response.toolName !== "delegate_task") {
+        continue;
+      }
+
+      const input = (response.toolInput || {}) as DelegationToolInput;
+      const targetAgentId = typeof input.agent_id === "string" ? input.agent_id : "";
+      const delegatedInstructions = typeof input.instructions === "string" ? input.instructions : "";
+      const toolUseId = response.toolUseId || `${agentId}-delegate-${invocation}`;
+      yield toolUseMessage(toolUseId, response.toolInput || {}, request.sessionId);
+
+      let result: AgentRunResult;
+      if (!targetAgentId || !globalRegistry.getAgent(targetAgentId) || !globalRegistry.getProviderForAgent(targetAgentId)) {
+        const missingAgent = targetAgentId || "(missing agent_id)";
+        result = { content: `Agent '${missingAgent}' not found or provider not available`, isError: true };
+        yield { type: "error", error: result.content };
+      } else if (delegationPath.includes(targetAgentId) || targetAgentId === agentId) {
+        result = { content: `Circular delegation detected for agent '${targetAgentId}'`, isError: true };
+        yield { type: "error", error: result.content };
+      } else {
+        result = yield* runAgentConversation(
+          targetAgentId,
+          request,
+          delegatedInstructions,
+          abortController,
+          debugMode,
+          [...delegationPath, agentId],
+          false,
+        );
+        if (!result.content && !result.isError) result.content = EMPTY_SUB_AGENT_OUTPUT;
+      }
+
+      const resultJson = toolResultPayload(toolUseId, result.content, result.isError);
+      yield toolResultMessage(toolUseId, result.content, result.isError, request.sessionId);
+      // Preserve the preceding tool use as context as well as the required JSON
+      // tool result, so providers that accept message history can continue the turn.
+      context.push({ role: "assistant", content: JSON.stringify({ type: "tool_use", id: toolUseId, name: "delegate_task", input: response.toolInput || {} }) });
+      context.push({ role: "user", content: resultJson });
+      delegated = true;
+      break;
+    }
+
+    if (!delegated) {
+      return { content: accumulatedText || EMPTY_SUB_AGENT_OUTPUT, isError: false };
+    }
+  }
+}
